# C implementation of container creation using clone() and namespaces:
#define _GNU_SOURCE
#include <sched.h>
#include <unistd.h>
#include <stdio.h>

int container_main(void *arg) {
    printf("Container PID inside namespace: %d\n", getpid()); // Prints: 1
    execvp("/bin/sh", NULL);
    return 0;
}

int main() {
    char stack[65536];
    // Spawn process in new UTS, PID, and Mount namespaces:
    clone(container_main, stack + sizeof(stack),
          CLONE_NEWUTS | CLONE_NEWPID | CLONE_NEWNS | SIGCHLD, NULL);
    return 0;
}

# Snippet of tini's signal forwarding loop (simplified C):
int main(int argc, char *argv[]) {
    prctl(PR_SET_CHILD_SUBREAPER, 1);
    pid_t child_pid = fork();
    if (child_pid == 0) {
        execvp(argv[1], &argv[1]); // Spawns application as child
    }

    // Reaping loop:
    while (1) {
        int status;
        pid_t pid = waitpid(-1, &status, WNOHANG);
        if (pid > 0) {
            // Zombie reaped successfully!
        }
        // Forward signals...
    }
}

